begin;
create extension if not exists pgtap with schema extensions;
set local search_path=extensions,public,api,private,pg_temp;
select no_plan();
select is(private.study_reporting_canonical('{"byteSize":2.0}'),'{"byteSize":2}','canonical safe integer metadata matches JSON-number serialization regardless of PostgreSQL numeric scale');
\ir fixtures/study904_analysis_fixture.sql
create temp table study904_report_results(k text primary key,v jsonb);
create function pg_temp.keep(p_key text,p_value jsonb) returns jsonb language plpgsql as $$begin insert into study904_report_results values(p_key,p_value) on conflict(k) do update set v=excluded.v;return p_value;end$$;
create function pg_temp.val(p_key text) returns jsonb language sql as $$select v from study904_report_results where k=p_key$$;
update private.study_reporting_config set analysis_enabled=true,report_enabled=true,export_enabled=true,export_profile=jsonb_build_object('issuerId','study904-test','keyId','study904-key','rendererVersion','1.0.0','viewModelVersion','lca.study-report-view.v1','rendererArtifactHash',repeat('a',64),'policyId','lca.study-report-disclosure.v1');
select pg_temp.study894_claim(1);
select pg_temp.keep('analysis',api.cmd_study_reporting_v1(pg_temp.study904_request('report-analysis')));
select pg_temp.study894_claim(null,null,true);
select pg_temp.keep('claim',private.worker_claim_jobs('solver','study904-report-sql',1,900));
select pg_temp.keep('facts',api.svc_study_analysis_complete_v1((pg_temp.val('analysis')->'data'->'value'->>'analysisId')::uuid,(pg_temp.val('claim')->'data'->0->>'id')::uuid,(pg_temp.val('claim')->'data'->0->>'leaseToken')::uuid,pg_temp.study904_completion(pg_temp.val('analysis')->'data'->'value'->>'configHash'),'report-facts'));
create function pg_temp.content() returns jsonb language sql as $$select jsonb_build_object('schemaVersion','lca.study-report-draft.v1','title','Synthetic SQL binding report','claims',jsonb_build_array(jsonb_build_object('claimId','claim-1','bundleRef',pg_temp.val('facts')->'data'->'value'->'factsRef','factId','fact-1','canonicalValue','1','unit','kg','display',jsonb_build_object('style','exact'))),'sections','[]'::jsonb,'tables','[]'::jsonb,'charts','[]'::jsonb,'additionalLimitations','[]'::jsonb)$$;
create function pg_temp.req(p_operation text,p_fields jsonb,p_key text) returns jsonb language sql as $$select jsonb_build_object('schemaVersion','lca.study-api.v3','requestId',p_key,'idempotencyKey',p_key,'operation',p_operation)||p_fields$$;
create function pg_temp.create_req(p_key text) returns jsonb language sql as $$select pg_temp.req('report.create',jsonb_build_object('studyId','89400000-0000-4000-8000-000000000010','parentReportRevisionId',null,'runIds',pg_temp.study904_config()->'runIds','analysisIds',jsonb_build_array(pg_temp.val('analysis')->'data'->'value'->'analysisId'),'content',pg_temp.content(),'templateId','lca.study-report.v1'),p_key)$$;
create function pg_temp.produced(p_id text,p_type text,p_schema text,p_name text,p_hash text,p_size integer default 2) returns jsonb language sql as $$select jsonb_build_object('studyId','89400000-0000-4000-8000-000000000010','artifactRef',jsonb_build_object('type',p_type,'id',p_id,'contentHash',p_hash,'digestScope','artifact_bytes_sha256','byteSize',p_size,'mediaType','application/json','schemaVersion',p_schema),'storageBucket','study-artifacts','storageObjectPath','study/89400000-0000-4000-8000-000000000010/'||p_id||'/'||p_name||'.json')$$;
create function pg_temp.validation(p_context jsonb,p_hash text) returns jsonb language sql as $$select jsonb_build_object('schemaVersion','lca.study-report-validation.v1','profileId','lca.study-report-claims.v1','reportRevisionId',p_context->'data'->'reportRevisionId','contentHash',p_hash,'claimCount',1,'factsBindingHash',p_context->'data'->'factsBindingHash')$$;
create function pg_temp.completion(p_context jsonb,p_hash text) returns jsonb language sql as $$select jsonb_build_object('kind','validatedContent','contentArtifact',pg_temp.produced(p_context->'data'->>'contentArtifactId','reportContent','lca.study-report-content.v1','content',p_hash),'factsRefs',jsonb_build_array(pg_temp.val('facts')->'data'->'value'->'factsRef'),'validation',pg_temp.validation(p_context,p_hash))$$;
select ok(not private.study_report_content_valid(jsonb_set(pg_temp.content(),'{title}','"<script>bad</script>"')),'direct SQL cannot persist HTML narrative');
select ok(not private.study_report_content_valid(jsonb_set(pg_temp.content(),'{claims,0,canonicalValue}','"1.0"')),'noncanonical numeric strings fail closed');
select ok(not private.study_report_content_valid(jsonb_set(pg_temp.content(),'{claims,0,display}','{"style":"rounded"}')),'formatting cannot reinterpret producer numerical spelling');
select ok(not has_table_privilege('service_role','private.study_report_revisions','INSERT'),'raw report writes remain closed even to ordinary service requests');
select ok(not has_function_privilege('authenticated','api.svc_study_report_intent_consume_v1(uuid,jsonb)','EXECUTE'),'only service may submit validated producer evidence');
select pg_temp.study894_claim(1);
select ok((pg_temp.keep('intent',api.cmd_study_reporting_v1(pg_temp.create_req('report-create')))->>'ok')::boolean,'inline draft enters opaque producer intent');
