select ok((pg_temp.keep('context',api.svc_study_report_intent_resolve_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid))->>'ok')::boolean,'service gets ordered current authorized producer context');
select is(pg_temp.val('context')->'data'->'report','null'::jsonb,'new report context does not pretend a draft exists');
select is(pg_temp.val('context')->'data'->'contentArtifact','null'::jsonb,'new report has no phantom issued content');
select is(pg_temp.val('context')->'data'->>'factsBindingHash',private.study_reporting_digest('lca.study-report-facts-binding.v1',jsonb_build_array(pg_temp.val('facts')->'data'->'value'->'factsRef')),'facts identity binds exact ordered ready Analysis refs');
savepoint stale_reporting_config;
update private.study_reporting_config set revision=revision+1;
select is(api.svc_study_report_intent_resolve_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid)->>'code','CAPABILITY_UNAVAILABLE','configuration change fences an unconsumed producer intent');
rollback to stale_reporting_config;
savepoint expired_report_intent;
update private.study_report_intents set expires_at=clock_timestamp()-interval '1 second' where id=(pg_temp.val('intent')->'data'->>'intentId')::uuid;
