update public.lifecyclemodels set state_code=20 where id='89400000-0000-4000-8000-000000000101';
select is(api.svc_study_report_intent_consume_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,pg_temp.completion(pg_temp.val('context'),repeat('b',64)))->>'code','DISCLOSURE_DENIED','source revocation between producer read and registration prevents all writes');
