select is(api.svc_study_report_intent_reconcile_v1(gen_random_uuid(),(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'state','unknown','unknown intent cannot recover another allocated artifact');
savepoint expired_reconcile;
update private.study_report_intents set expires_at=clock_timestamp()-interval '1 second' where id=(pg_temp.val('intent')->'data'->>'intentId')::uuid;
select is(api.svc_study_report_intent_reconcile_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'state','expired_unreferenced','expired unconsumed exact allocation is retained as unreferenced metadata');
select is(api.svc_study_report_intent_consume_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,pg_temp.completion(pg_temp.val('context'),repeat('b',64)))->>'code','CAPABILITY_UNAVAILABLE','expired original intent cannot later register that allocation');
