savepoint referenced_reconcile;
select private.study_store_artifact('89400000-0000-4000-8000-000000000010',pg_temp.produced(pg_temp.val('context')->'data'->>'contentArtifactId','reportContent','lca.study-report-content.v1','content',repeat('d',64))->'artifactRef','study-artifacts',pg_temp.produced(pg_temp.val('context')->'data'->>'contentArtifactId','reportContent','lca.study-report-content.v1','content',repeat('d',64))->>'storageObjectPath','reportContent');
select is(api.svc_study_report_intent_reconcile_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'state','referenced','any registered allocated ID blocks orphan treatment even with a different reported hash');
