select is(api.svc_study_report_intent_reconcile_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'state','pending','revoked actor cannot turn unknown bytes into cleanup authority');
select is(api.svc_study_report_intent_consume_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,pg_temp.completion(pg_temp.val('context'),repeat('b',64)))->>'code','FORBIDDEN','reconcile never restores revoked actor consume rights');
