select is(api.svc_study_report_intent_reconcile_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'deletionPermitted','false','no reconciliation result grants deletion authority');
savepoint committed_revoked_reconcile;
delete from private.study_members where study_id='89400000-0000-4000-8000-000000000010' and actor_id='89400000-0000-4000-8000-000000000001';
select is(api.svc_study_report_intent_reconcile_v1((pg_temp.val('intent')->'data'->>'intentId')::uuid,(pg_temp.val('context')->'data'->>'contentArtifactId')::uuid,repeat('b',64))->'data'->>'state','committed','privileged locator-free audit survives actor revocation without restoring disclosure');
