select is(api.cmd_study_reporting_v1(pg_temp.create_req('report-create')),pg_temp.val('report'),'actor replay redirects to final record after intent TTL');
select pg_temp.keep('save-intent',api.cmd_study_reporting_v1(pg_temp.req('report.save',jsonb_build_object('target',jsonb_build_object('type','reportRevision','id',pg_temp.val('report')->'data'->'value'->'reportRevisionId','expectedRevision',1),'content',jsonb_set(pg_temp.content(),'{title}','"Saved synthetic content"')),'report-save')));
