select pg_temp.keep('freeze-intent',api.cmd_study_reporting_v1(pg_temp.req('report.freeze',jsonb_build_object('target',jsonb_build_object('type','reportRevision','id',pg_temp.val('saved')->'data'->'value'->'reportRevisionId','expectedRevision',2),'expectedContentHash',repeat('c',64)),'report-freeze')));
