select ok((pg_temp.keep('frozen',api.svc_study_report_intent_consume_v1((pg_temp.val('freeze-intent')->'data'->>'intentId')::uuid,jsonb_build_object('kind','validatedFreeze','contentRef',pg_temp.val('saved')->'data'->'value'->'contentRef','validation',pg_temp.validation(pg_temp.val('freeze-context'),repeat('c',64)))))->>'ok')::boolean,'freeze revalidates exact registered content and facts before atomic transition');
