select pg_temp.keep('export-intent',api.cmd_study_reporting_v1(pg_temp.req('export.request',jsonb_build_object('reportRevisionId',pg_temp.val('frozen')->'data'->'value'->'reportRevisionId','expectedContentHash',repeat('c',64),'rendererVersion','1.0.0','viewModelVersion','lca.study-report-view.v1'),'report-export')));
